-- fdh-c-check: op row count of ORF
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (2, in order of the placeholders): start, end
-- returns n
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e) SELECT COUNT(*) AS n FROM p JOIN ovst v FORCE INDEX (ix_vstdate) ON v.vstdate BETWEEN p.s AND p.e INNER JOIN referout ro ON ro.vn = v.vn WHERE (v.an IS NULL OR v.an = '') AND TRIM(COALESCE(ro.refer_hospcode, ro.hospcode, '')) NOT IN ('', (SELECT hospitalcode FROM opdconfig LIMIT 1));
